CREATE TABLE IF NOT EXISTS employee_profiles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL UNIQUE REFERENCES people_records(id) ON DELETE CASCADE, employee_number text UNIQUE, job_title text, department text, manager_person_id uuid REFERENCES people_records(id) ON DELETE SET NULL, employment_type text DEFAULT 'full_time', hire_date date, work_email text, phone text, address text, date_of_birth date, gender text, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS employee_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, document_type text NOT NULL, document_name text NOT NULL, storage_url text, status text NOT NULL DEFAULT 'pending', expires_on date, uploaded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS leave_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, leave_type text NOT NULL, start_date date NOT NULL, end_date date NOT NULL, days numeric(6,2), reason text, status text NOT NULL DEFAULT 'pending', approved_by uuid REFERENCES people_records(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS attendance_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, work_date date NOT NULL, check_in timestamptz, check_out timestamptz, status text NOT NULL DEFAULT 'present', notes text, UNIQUE(person_id,work_date));
CREATE TABLE IF NOT EXISTS employee_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, request_type text NOT NULL, subject text NOT NULL, details text, status text NOT NULL DEFAULT 'open', assigned_to uuid REFERENCES people_records(id) ON DELETE SET NULL, created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS employee_certifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, certification_name text NOT NULL, issuing_body text, certificate_number text, issued_on date, expires_on date, status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS emergency_contacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), person_id uuid NOT NULL REFERENCES people_records(id) ON DELETE CASCADE, full_name text NOT NULL, relationship text NOT NULL, phone text NOT NULL, email text, address text, is_primary boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS idx_employee_profiles_manager ON employee_profiles(manager_person_id);
CREATE INDEX IF NOT EXISTS idx_leave_person_status ON leave_requests(person_id,status);
CREATE INDEX IF NOT EXISTS idx_attendance_person_date ON attendance_records(person_id,work_date);
CREATE INDEX IF NOT EXISTS idx_requests_person_status ON employee_requests(person_id,status);
CREATE INDEX IF NOT EXISTS idx_documents_person ON employee_documents(person_id);